param([Parameter(Mandatory=$true)][string]$Domain,[string]$BackupDirectory,[int]$MaximumBackupAgeHours=30)
$ErrorActionPreference='Stop';& (Join-Path $PSScriptRoot 'health-check.ps1') -Url "https://$Domain/api/ready";$tcp=Test-NetConnection -ComputerName $Domain -Port 443 -WarningAction SilentlyContinue;if(-not$tcp.TcpTestSucceeded){throw 'HTTPS port is unreachable'};if($BackupDirectory){$latest=Get-ChildItem -LiteralPath $BackupDirectory -Filter'warevanta-staging-*.dump'|Sort-Object LastWriteTime -Descending|Select-Object -First 1;if(-not$latest){throw 'No staging backup found'};$age=((Get-Date)-$latest.LastWriteTime).TotalHours;if($age-gt$MaximumBackupAgeHours){throw "Latest backup is $([math]::Round($age,1)) hours old"};Write-Output "Latest verified-backup candidate is $([math]::Round($age,1)) hours old."}
